package main

import (
	"context"
	"fmt"
	"time"
)

// worker 监听 ctx 取消和 jobs 关闭两条退出路径，缺一不可
func worker(ctx context.Context, jobs <-chan int) {
	for {
		select {
		case <-ctx.Done():
			fmt.Printf("worker canceled: %v\n", ctx.Err())
			return
		case job, ok := <-jobs:
			if !ok {
				return
			}
			handle(job)
		}
	}
}

// startWorker 派生可取消的 ctx，返回 cancel 给调用方
func startWorker(parent context.Context, jobs <-chan int) context.CancelFunc {
	ctx, cancel := context.WithCancel(parent)
	go worker(ctx, jobs)
	return cancel // 调用方在请求结束、任务撤销或服务关闭时调用
}

func handle(job int) { time.Sleep(10 * time.Millisecond) }

func main() {
	jobs := make(chan int, 100)
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	startWorker(ctx, jobs)
	for i := 0; i < 10; i++ {
		jobs <- i
	}
	time.Sleep(6 * time.Second) // ctx 超时后 worker 自动退出，不会泄漏
	fmt.Println("done, goroutine count:", runtime.NumGoroutine())
}

package main

import (
	"fmt"
	"runtime"
	"sync"
	"time"
)

func main() {
	fmt.Println("GOMAXPROCS:", runtime.GOMAXPROCS(0))

	// 创建大量短生命周期 goroutine，观察调度器行为
	var wg sync.WaitGroup
	for i := 0; i < 100000; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			_ = make([]byte, 1024) // 触发栈增长
		}()
	}
	wg.Wait()
	fmt.Println("goroutines after work:", runtime.NumGoroutine())

	// 演示阻塞 syscall 导致线程数膨胀
	// 环境变量 GODEBUG=schedtrace=1000 可观察 P/M/runq 变化
	// 环境变量 GODEBUG=schedtrace=1000,scheddetail=1 查看每个 P 的详情
	fmt.Println("hint: run with GODEBUG=schedtrace=1000,scheddetail=1")
}
